from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")
_DATE_FORMATS = ("%Y-%m-%d", "%d/%m/%Y", "%Y/%m/%d")


def parse_date(value) -> date:
    """Accept date objects, ISO strings, and legacy DD/MM/YYYY or YYYY/MM/DD strings."""
    if isinstance(value, date):
        return value
    text = str(value).strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    raise ValueError(f"unrecognised date: {value!r}")


def parse_amount(value) -> Decimal:
    """Normalise str/float/Decimal amounts (including legacy '$4.50') to cents."""
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, float):
        amount = Decimal(repr(value))
    else:
        cleaned = re.sub(r"[^0-9.\-]", "", str(value))
        if not cleaned:
            raise ValueError(f"unrecognised amount: {value!r}")
        # Values entered as text are stored as given.
        return Decimal(cleaned)
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Transaction:
    id: str
    date: date
    amount: Decimal
    category: str
    note: str = ""

    def to_json(self) -> dict:
        return {
            "id": self.id,
            "date": self.date.isoformat(),
            "amount": str(self.amount),
            "category": self.category,
            "note": self.note,
        }

    @classmethod
    def from_json(cls, record: dict) -> "Transaction":
        return cls(
            id=str(record["id"]),
            date=parse_date(record["date"]),
            amount=parse_amount(record["amount"]),
            category=str(record["category"]).strip(),
            note=str(record.get("note", "")).strip(),
        )
